section .data
%include "assets/map_text/mt_moon_pokecenter.inc"

section .text

%assign event_byte -1
%assign event_byte_a -1
MtMoonPokecenter_Script:
    call Serial_TryEstablishingExternallyClockedConnection
    jmp EnableAutoTextBoxDrawing

%assign event_byte -1
%assign event_byte_a -1
MtMoonPokecenter_TextPointers:
    dd MtMoonPokecenterNurseText
    dd MtMoonPokecenterYoungsterText
    dd MtMoonPokecenterGentlemanText
    dd MtMoonPokecenterMagikarpSalesmanText
    dd MtMoonPokecenterClipboardText
    dd MtMoonPokecenterLinkReceptionistText
    dd MtMoonPokecenterChanseyText
MtMoonPokecenterNurseText:
    script_pokecenter_nurse
MtMoonPokecenterYoungsterText:
    text_far _MtMoonPokecenterYoungsterText
    text_end
MtMoonPokecenterGentlemanText:
    text_far _MtMoonPokecenterGentlemanText
    text_end

%assign event_byte -1
%assign event_byte_a -1
MtMoonPokecenterMagikarpSalesmanText:
; DEVIATION{class=banking; pret=macros/farcall.asm:callfar; behavior=bank switch dropped, call goes straight to the target; evidence=the DPMI model is flat so every routine is always addressable, and Bankswitch has no port counterpart; lifetime=permanent}
    call MagikarpSalesman
    jmp TextScriptEnd

%assign event_byte -1
%assign event_byte_a -1
MtMoonPokecenterClipboardText:
    text_far _MtMoonPokecenterClipboardText
    text_end
MtMoonPokecenterLinkReceptionistText:
    script_cable_club_receptionist

%assign event_byte -1
%assign event_byte_a -1
MtMoonPokecenterChanseyText:
; DEVIATION{class=banking; pret=macros/farcall.asm:callfar; behavior=bank switch dropped, call goes straight to the target; evidence=the DPMI model is flat so every routine is always addressable, and Bankswitch has no port counterpart; lifetime=permanent}
    call PokecenterChanseyText
    jmp TextScriptEnd

%assign event_byte -1
%assign event_byte_a -1
MagikarpSalesman:
    CheckEvent EVENT_BOUGHT_MAGIKARP, 1
    jb .alreadyBoughtMagikarp
    mov esi, .IGotADealText
    call PrintText
    mov al, MONEY_BOX
    mov [ebp + wTextBoxID], al
    call DisplayTextBoxID
    call YesNoChoice
    mov al, [ebp + wCurrentMenuItem]
    test al, al
    jnz .choseNo
    xor al, al
    mov [ebp + hMoney], al
    mov [ebp + hMoney + 2], al
    mov al, 0x5
    mov [ebp + hMoney + 1], al
    call HasEnoughMoney
    jae .enoughMoney
    mov esi, .NoMoneyText
    jmp .printText

%assign event_byte -1
%assign event_byte_a -1
.enoughMoney:
    mov bx, ((MAGIKARP) << 8) | (5)
    call GivePokemon
    jae .done
    xor al, al
    mov [ebp + wPriceTemp], al
    mov [ebp + wPriceTemp + 2], al
    mov al, 0x5
    mov [ebp + wPriceTemp + 1], al
    mov esi, wPriceTemp + 2
    mov dx, wPlayerMoney + 2
    mov bl, 0x3
; DEVIATION{class=banking; pret=macros/predef.asm:predef; behavior=Predef dispatch replaced by a direct call, and A is left holding whatever the callee left rather than pret's parent ROM bank; evidence=pret Predef saves hLoadedROMBank with push af and restores it with pop af before returning so A holds a BANK NUMBER on return - not the predef id - and the flat DPMI model has no banks for that value to mean anything, plus dataflow shows no direct read of A after this site; lifetime=retired when PredefPointers is ported}
    call SubBCDPredef
    mov al, MONEY_BOX
    mov [ebp + wTextBoxID], al
    call DisplayTextBoxID
    SetEvent EVENT_BOUGHT_MAGIKARP
    jmp .done

%assign event_byte -1
%assign event_byte_a -1
.choseNo:
    mov esi, .NoText
    jmp .printText

%assign event_byte -1
%assign event_byte_a -1
.alreadyBoughtMagikarp:
    mov esi, .NoRefundsText
.printText:
    call PrintText
.done:
    ret

%assign event_byte -1
%assign event_byte_a -1
.IGotADealText:
    text_far _MtMoonPokecenterMagikarpSalesmanIGotADealText
    text_end
.NoText:
    text_far _MtMoonPokecenterMagikarpSalesmanNoText
    text_end
.NoMoneyText:
    text_far _MtMoonPokecenterMagikarpSalesmanNoMoneyText
    text_end
.NoRefundsText:
    text_far _MtMoonPokecenterMagikarpSalesmanNoRefundsText
    text_end
